-- INFERRED global child names from native Blizzard_MacroUI.lua/xml.
ShowMacroFrame()
assert(MacroFrame:IsShown())
assert(PanelTemplates_GetSelectedTab(MacroFrame) == 1)
local account, character = GetNumMacros()
assert(account == 2 and character == 1, "supplied macro counts")
assert(MacroButton1:IsEnabled() and MacroButton2:IsEnabled())
assert(not MacroButton3:IsEnabled(), "empty macro slot disabled")
assert(MacroButton1Name:GetText() == "Raid Beacon")
assert(MacroFrameSelectedMacroName:GetText() == "Raid Beacon")
assert(MacroFrameText:GetText() == "/rw Stack on star")
assert(MacroFrameSelectedMacroButtonIcon:GetTexture() == 134400)
